css:
.check {
  display: none;
}

.hamburger-button {
  position: relative;
  display: inline-block;
  width: 70px;
  height: 50px;
  cursor: pointer;
}

.hamburger-button div {
  width: 70px;
  height: 10px;
  background-color: darkgray;
  border-radius: 3px;
  position: absolute;
  transition: 0.4s;
}

.line1 {
  top: 0;
}

.line2 {
  top: calc(40%);
}

.line3 {
  top: calc(80%);
}

.hamburger-button:hover div {
  width: 54.2857143%;
}

.hamburger-button:hover .line1 {
  transform: translate(31.5px, 12px) rotate(35deg);
  border-radius: 7px;
  border-top-right-radius: 10px;
  border-bottom-right-radius: 10px;
}

.hamburger-button:hover .line3 {
  transform: translate(31.5px, -12px) rotate(-35deg);
  border-radius: 7px;
  border-top-right-radius: 10px;
  border-bottom-right-radius: 10px;
}

.check:checked ~ .hamburger-button:hover .line1 {
  transform: translate(0, 12px) rotate(-35deg);
  border-radius: 7px;
  border-top-left-radius: 10px;
  border-bottom-left-radius: 10px;
}

.check:checked ~ .hamburger-button:hover .line3 {
  transform: translate(0, -12px) rotate(35deg);
  border-radius: 7px;
  border-top-left-radius: 10px;
  border-bottom-left-radius: 10px;
}

.check:checked ~ .hamburger-button:hover .line2 {
  margin-left: 32px;
}
